success = 0
fail = 0
results = []

for code, data in stocks:
    payload = json.dumps({"code": code, "data": data}).encode("utf-8")
    req = urllib.request.Request(API, data=payload, headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            body = json.loads(resp.read().decode())
            ok = body.get("success", False)
            if ok:
                success += 1
                results.append(f"OK  {code} {data['BaseInfo']['Name']}")
            else:
                fail += 1
                results.append(f"ERR {code} {data['BaseInfo']['Name']} -> {body}")
    except Exception as e:
        fail += 1
        results.append(f"EXC {code} {data['BaseInfo']['Name']} -> {e}")

print(f"\n=== POST Result: Success {success}/{len(stocks)}, Fail {fail} ===")
for r in results:
    print(r)
